import os

def open_file(filename, flags):
    return os.open(filename, flags)

def close_file(fd):
    os.close(fd)

def write_to_file(fd, data):
    return os.write(fd, data.encode())

def read_from_file(fd, size):
    return os.read(fd, size).decode()

def unlink_file(filename):
    os.unlink(filename)

def lseek_file(fd, offset, whence):
    return os.lseek(fd, offset, whence)

