import os

# Dosyayı yalnızca yazmak için aç, dosya mevcut değilse oluştur, mevcutsa hata ver
def create_unique_file(filename):
    try:
        fd = os.open(filename, os.O_WRONLY | os.O_CREAT | os.O_EXCL)
        os.close(fd)
        print(f"Dosya başarıyla oluşturuldu: {filename}")
    except FileExistsError:
        print(f"Dosya zaten mevcut: {filename}")
    except Exception as e:
        print(f"Hata oluştu: {e}")

# Dosyayı yalnızca yazmak için aç, dosya mevcut değilse oluştur, mevcutsa içeriğini temizle
def truncate_and_write_file(filename):
    try:
        fd = os.open(filename, os.O_WRONLY | os.O_CREAT | os.O_TRUNC)
        os.close(fd)
        print(f"Dosya başarıyla oluşturuldu veya temizlendi: {filename}")
    except Exception as e:
        print(f"Hata oluştu: {e}")

# Kullanım örnekleri
create_unique_file("test.txt")
truncate_and_write_file("test2.txt")
